def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    bg=max({v for row in grid for v in row}, key=lambda v:sum(row.count(v) for row in grid))
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and grid[r][c] != 2:
                color=grid[r][c]
                out[r][c]=4
                for rr in range(r+1,h):
                    if grid[rr][c] != bg: break
                    out[rr][c]=color
    return out

