cat > programs/task-aa0d0e1f.py <<'PY'
def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    from collections import Counter
    cnt=Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    colors=[v for v in cnt if v!=bg]
    marker=max(colors,key=lambda v:cnt[v])
    obj=next(v for v in colors if v!=marker)
    # object color is painted in any complete marker-indexed row/column bands;
    # isolated object pixels are converted to 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c]==obj: out[r][c]=4
    # marker runs that touch left/right edges specify rows to fill;
    # runs touching top/bottom specify columns.
    for r in range(h):
        if grid[r][0]==marker or grid[r][-1]==marker:
            for c in range(w):
                if grid[r][c]==bg: out[r][c]=obj
    for c in range(w):
        if grid[0][c]==marker or grid[-1][c]==marker:
            for r in range(h):
                if grid[r][c]==bg: out[r][c]=obj
    return out
PY

