def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    counts=Counter(x for row in grid for x in row)
    bg=counts.most_common(1)[0][0]
    colors=[x for x in counts if x!=bg]
    marker=max(colors,key=lambda x:counts[x])
    obj=next(x for x in colors if x!=marker)
    # A border run casts a perpendicular stripe inward, extending the
    # non-background field color. Existing object marks become 4.
    for r in range(h):
        if grid[r][0] == marker or grid[r][w-1] == marker:
            for c in range(w):
                if grid[r][c] == bg and c not in (0,w-1): out[r][c] = obj
                elif grid[r][c] == obj: out[r][c] = 4
    for c in range(w):
        if grid[0][c] == marker or grid[h-1][c] == marker:
            for r in range(h):
                if grid[r][c] == bg and r not in (0,h-1): out[r][c] = obj
                elif grid[r][c] == obj: out[r][c] = 4
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker: out[r][c] = marker
    return out

