    from collections import Counter
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    counts=Counter(v for row in grid for v in row)
    bg=counts.most_common(1)[0][0]
    colors=[v for v in counts if v!=bg]
    marker=max(colors,key=lambda v:counts[v])
    fill=next(v for v in colors if v!=marker)

    def groups(indices):
        result=[]
        for i in indices:
            if not result or i != result[-1][-1]+1:
                result.append([i])
            else:
                result[-1].append(i)
        return result

    # The first cell/row of each continuous boundary marker segment is its
    # anchor. Subsequent positions cast inward bands of the other color.
    for edge in (0,w-1):
        rows=[r for r in range(h) if grid[r][edge]==marker]
        for run in groups(rows):
            for r in run[1:]:
                direction=1 if edge==0 else -1
                seed=next((c for c in range(w) if grid[r][c]==fill),None)
                end=(seed if seed is not None else (w-1 if edge==0 else 0))
                for c in range((1 if edge==0 else w-2), end+direction, direction):
                    if grid[r][c]==bg: out[r][c]=fill
                    elif grid[r][c]==fill: out[r][c]=4
    for edge in (0,h-1):
        cols=[c for c in range(w) if grid[edge][c]==marker]
        for run in groups(cols):
            for c in run[1:]:
                direction=1 if edge==0 else -1
                seed=next((r for r in range(h) if grid[r][c]==fill),None)
                end=(seed if seed is not None else (h-1 if edge==0 else 0))
                for r in range((1 if edge==0 else h-2), end+direction, direction):
                    if grid[r][c]==bg: out[r][c]=fill
                    elif grid[r][c]==fill: out[r][c]=4
    for r in range(h):
        for c in range(w):
            if grid[r][c]==marker: out[r][c]=marker
    return out
