def transform(grid):
    out=[row[:] for row in grid]
    # The isolated 8 on the row with the right-hand 1 rail marks a horizontal
    # band: spread 8 through the intervening cells and convert its seed to 4.
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==8:
                out[r][c]=4
                for k in range(c+1,len(row)):
                    if grid[r][k]==1:
                        break
                    if grid[r][k]==9:
                        out[r][k]=8
    return out
