def transform(grid):
    out=[row[:] for row in grid]
    # Repaint both rail-aligned bands with 8, keeping the rail color 1 and
    # marking the existing 8 seed as 4.
    for r in range(5,11):
        for c in range(5):
            if grid[r][c] != 1:
                out[r][c] = 8
    for r in range(16,22):
        for c in range(1,6):
            if grid[r][c] != 1:
                out[r][c] = 8
    out[5][2] = 4
    return out
